//! `kiri vm`: configure macOS VM networking in `~/.kiri/vm.json` (`shared_nat`).
//!
//! Disabling shared NAT (`kiri vm set --shared-nat off`) boots the macOS VM
//! without `VZNATNetworkDeviceAttachment` (`InternetSharing`), routing container
//! outbound TCP and DNS through the Mac over vsock instead. This avoids
//! `InternetSharing` conflicts with Cloudflare WARP (#383) and corporate
//! firewalls that drop non-DF packets generated by `InternetSharing` (#350).

use std::io;
use std::path::Path;

use serde_json::{Value, json};

use crate::client;
use crate::daemon::engine;

const USAGE: &str = "\
usage: kiri vm [status]                      VM networking settings and running state
       kiri vm set --shared-nat on|off       toggle macOS shared NAT (InternetSharing) in vm.json";

#[derive(Debug, PartialEq, Eq)]
enum Cmd {
    Help,
    Status,
    Set { shared_nat: bool },
}

fn parse_on_off(flag: &str, v: Option<&str>) -> Result<bool, String> {
    let raw = v.ok_or_else(|| format!("{flag} needs on or off"))?;
    engine::parse_bool_env(raw).ok_or_else(|| format!("{flag}: expected on or off, got {raw}"))
}

fn parse(args: &[String]) -> Result<Cmd, String> {
    match args.first().map(String::as_str) {
        None => Ok(Cmd::Status),
        Some("status") if args.len() == 1 => Ok(Cmd::Status),
        Some("-h" | "--help" | "help") if args.len() == 1 => Ok(Cmd::Help),
        Some("set") => {
            let mut shared_nat = None;
            let mut it = args[1..].iter().map(String::as_str);
            while let Some(a) = it.next() {
                let (flag, inline) = a.split_once('=').map_or((a, None), |(f, v)| (f, Some(v)));
                match flag {
                    "--shared-nat" => shared_nat = Some(parse_on_off(flag, inline.or_else(|| it.next()))?),
                    "-h" | "--help" => return Ok(Cmd::Help),
                    _ => return Err(USAGE.into()),
                }
            }
            match shared_nat {
                Some(v) => Ok(Cmd::Set { shared_nat: v }),
                None => Err(USAGE.into()),
            }
        }
        _ => Err(USAGE.into()),
    }
}

fn read_vm_json(path: &Path) -> io::Result<Value> {
    match std::fs::read(path) {
        Ok(bytes) => {
            let v: Value = serde_json::from_slice(&bytes)
                .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, format!("{}: {e}", path.display())))?;
            if v.is_object() {
                Ok(v)
            } else {
                Err(io::Error::new(io::ErrorKind::InvalidData, format!("{}: expected a JSON object", path.display())))
            }
        }
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(json!({})),
        Err(e) => Err(e),
    }
}

fn save_shared_nat(path: &Path, enabled: bool) -> io::Result<Value> {
    let mut cfg = read_vm_json(path)?;
    cfg["shared_nat"] = json!(enabled);
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let tmp = path.with_extension(format!("json.tmp.{}", std::process::id()));
    std::fs::write(&tmp, cfg.to_string()).and_then(|()| std::fs::rename(&tmp, path))?;
    Ok(cfg)
}

/// Saves `shared_nat` in `~/.kiri/vm.json` while preserving other keys (`cpus`,
/// `memory_mib`, `disk_gb`). Used by Settings → Network.
pub(crate) fn set_shared_nat(enabled: bool) -> io::Result<()> {
    let path = engine::resources_path().ok_or_else(|| io::Error::other("HOME is not set"))?;
    save_shared_nat(&path, enabled).map(|_| ())
}

fn on_off(b: bool) -> &'static str {
    if b { "on" } else { "off" }
}

fn format_status(configured: Option<bool>, env_override: Option<bool>, path: &Path, info: Option<&Value>) -> String {
    let effective = env_override.or(configured).unwrap_or(true);
    let mut out = format!("shared NAT: {}", on_off(effective));
    if env_override.is_some() {
        out.push_str(" (set by KIRI_SHARED_NAT)");
    } else if configured.is_none() {
        out.push_str(" (default)");
    }
    out.push('\n');
    if let Some(info) = info {
        if info["KiriVmAwake"] == true {
            let mode = info["KiriVmUplink"]["mode"].as_str().unwrap_or("");
            let running_nat = mode != "host-egress";
            let detail = if running_nat {
                "shared NAT (VZNATNetworkDeviceAttachment)"
            } else {
                "host egress over vsock (shared NAT off)"
            };
            out.push_str(&format!("running VM: {detail}"));
            if running_nat != effective {
                out.push_str(&format!(" — restart Kiri to apply shared NAT {}", on_off(effective)));
            }
            out.push('\n');
        } else {
            out.push_str("running VM: asleep (applies on next start)\n");
        }
    }
    out.push_str(&format!("in {}\n", path.display()));
    out
}

pub fn run(args: &[String]) -> io::Result<()> {
    let cmd = parse(args).map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
    if cmd == Cmd::Help {
        println!("{USAGE}");
        return Ok(());
    }
    let path = engine::resources_path().ok_or_else(|| io::Error::other("HOME is not set"))?;
    let info = client::alive().then(|| client::get_background("/info").ok()).flatten();
    let env_override = engine::shared_nat_env();
    match cmd {
        Cmd::Help => unreachable!(),
        Cmd::Status => {
            let configured = read_vm_json(&path).ok().and_then(|v| v["shared_nat"].as_bool());
            print!("{}", format_status(configured, env_override, &path, info.as_ref()));
            Ok(())
        }
        Cmd::Set { shared_nat } => {
            save_shared_nat(&path, shared_nat)?;
            print!("{}", format_status(Some(shared_nat), env_override, &path, info.as_ref()));
            if env_override.is_some_and(|v| v != shared_nat) {
                eprintln!("kiri: note: KIRI_SHARED_NAT is set in this environment and takes precedence over vm.json");
            }
            Ok(())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn args(s: &str) -> Vec<String> {
        s.split_whitespace().map(String::from).collect()
    }

    #[test]
    fn parses_status_help_and_set() {
        assert_eq!(parse(&[]), Ok(Cmd::Status));
        assert_eq!(parse(&args("status")), Ok(Cmd::Status));
        assert_eq!(parse(&args("--help")), Ok(Cmd::Help));
        assert_eq!(parse(&args("-h")), Ok(Cmd::Help));
        assert_eq!(parse(&args("help")), Ok(Cmd::Help));
        assert_eq!(parse(&args("set --shared-nat off")), Ok(Cmd::Set { shared_nat: false }));
        assert_eq!(parse(&args("set --shared-nat on")), Ok(Cmd::Set { shared_nat: true }));
        assert_eq!(parse(&args("set --shared-nat=false")), Ok(Cmd::Set { shared_nat: false }));
        assert_eq!(parse(&args("set --shared-nat=1")), Ok(Cmd::Set { shared_nat: true }));
        assert_eq!(parse(&args("set --help")), Ok(Cmd::Help));
    }

    #[test]
    fn rejects_invalid_args() {
        assert_eq!(parse(&args("set --shared-nat")), Err("--shared-nat needs on or off".into()));
        assert_eq!(parse(&args("set --shared-nat maybe")), Err("--shared-nat: expected on or off, got maybe".into()));
        for bad in ["set", "set --nat off", "status extra", "bogus"] {
            assert!(parse(&args(bad)).unwrap_err().starts_with("usage:"), "{bad}");
        }
    }

    #[test]
    fn not_a_docker_command() {
        assert!(!crate::docker::handles("vm"));
    }

    #[test]
    fn save_shared_nat_creates_and_preserves_existing_vm_json_keys() {
        let dir = std::env::temp_dir().join(format!(
            "kiri-vm-cli-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_nanos()
        ));
        let path = dir.join("vm.json");

        // Creating vm.json from scratch sets shared_nat without requiring cpus/memory.
        save_shared_nat(&path, false).unwrap();
        assert_eq!(read_vm_json(&path).unwrap(), json!({"shared_nat": false}));

        // Existing resources fields (cpus, memory_mib, disk_gb) are preserved.
        std::fs::write(&path, r#"{"cpus":4,"memory_mib":8192,"disk_gb":128}"#).unwrap();
        save_shared_nat(&path, false).unwrap();
        assert_eq!(
            read_vm_json(&path).unwrap(),
            json!({"cpus": 4, "memory_mib": 8192, "disk_gb": 128, "shared_nat": false})
        );
        save_shared_nat(&path, true).unwrap();
        assert_eq!(
            read_vm_json(&path).unwrap(),
            json!({"cpus": 4, "memory_mib": 8192, "disk_gb": 128, "shared_nat": true})
        );

        let _ = std::fs::remove_dir_all(dir);
    }

    #[test]
    fn format_status_reflects_defaults_env_and_restart_needed() {
        let path = Path::new("/tmp/vm.json");
        let def = format_status(None, None, path, None);
        assert!(def.contains("shared NAT: on (default)"), "{def}");

        let off = format_status(
            Some(false),
            None,
            path,
            Some(&json!({"KiriVmAwake": true, "KiriVmUplink": {"mode": "dhcp"}})),
        );
        assert!(off.contains("shared NAT: off\n"), "{off}");
        assert!(off.contains("restart Kiri to apply shared NAT off"), "{off}");

        let aligned = format_status(
            Some(false),
            None,
            path,
            Some(&json!({"KiriVmAwake": true, "KiriVmUplink": {"mode": "host-egress"}})),
        );
        assert!(aligned.contains("host egress over vsock (shared NAT off)\n"), "{aligned}");
        assert!(!aligned.contains("restart Kiri"), "{aligned}");

        let overridden = format_status(Some(true), Some(false), path, None);
        assert!(overridden.contains("shared NAT: off (set by KIRI_SHARED_NAT)"), "{overridden}");
    }
}
